import { MealOrderItemSchema } from '#database/schema'
import { belongsTo } from '@adonisjs/lucid/orm'
import type { BelongsTo } from '@adonisjs/lucid/types/relations'
import Meal from '#models/meal'
import MenuItem from '#models/menu_item'
import MealOrder from '#models/meal_order'

/**
 * One line of an order with its price snapshot (`unitPriceCents`, D1).
 * `lineTotalCents` is generated by PostgreSQL — never written by the app.
 * The meal relation is a plain belongsTo so deleted meals stay readable in
 * history and statements.
 */
export default class MealOrderItem extends MealOrderItemSchema {
  @belongsTo(() => MealOrder)
  declare order: BelongsTo<typeof MealOrder>

  @belongsTo(() => Meal)
  declare meal: BelongsTo<typeof Meal>

  @belongsTo(() => MenuItem)
  declare menuItem: BelongsTo<typeof MenuItem>
}
